import{_ as t,o as a,c as i,an as r}from"./chunks/framework.BAJgIXXb.js";const p=JSON.parse('{"title":"OSCP · Fondamentaux d’Active Directory","description":"Domaine, authentification et droits de réplication Active Directory.","frontmatter":{"title":"OSCP · Fondamentaux d’Active Directory","description":"Domaine, authentification et droits de réplication Active Directory."},"headers":[],"relativePath":"oscp/ad-theorie.md","filePath":"oscp/ad-theorie.md"}'),o={name:"oscp/ad-theorie.md"};function s(n,e,d,l,c,h){return a(),i("div",null,e[0]||(e[0]=[r('<h1 id="fondamentaux-d-active-directory" tabindex="-1">Fondamentaux d’Active Directory <a class="header-anchor" href="#fondamentaux-d-active-directory" aria-label="Permalink to &quot;Fondamentaux d’Active Directory&quot;">​</a></h1><h2 id="domaine-et-controleur-de-domaine" tabindex="-1">Domaine et contrôleur de domaine <a class="header-anchor" href="#domaine-et-controleur-de-domaine" aria-label="Permalink to &quot;Domaine et contrôleur de domaine&quot;">​</a></h2><p>Un domaine regroupe des objets de l’annuaire, dont les comptes, les groupes et les ordinateurs. Un contrôleur de domaine héberge une copie de l’annuaire et fournit notamment les services LDAP et Kerberos.</p><h2 id="authentification" tabindex="-1">Authentification <a class="header-anchor" href="#authentification" aria-label="Permalink to &quot;Authentification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Terme</th><th>Rôle</th></tr></thead><tbody><tr><td>TGT</td><td>Ticket initial qui permet au client de demander un ticket pour un service.</td></tr><tr><td>TGS</td><td>Service Kerberos qui délivre les tickets de service.</td></tr><tr><td>Ticket de service</td><td>Ticket présenté au service demandé pour authentifier le client.</td></tr><tr><td>SPN</td><td>Nom qui associe une instance de service au compte sous lequel elle s’exécute.</td></tr><tr><td>NTLM</td><td>Famille de protocoles Windows utilisant notamment un échange de défi et de réponse.</td></tr></tbody></table><h2 id="indicateur-de-compte-et-droit-de-replication" tabindex="-1">Indicateur de compte et droit de réplication <a class="header-anchor" href="#indicateur-de-compte-et-droit-de-replication" aria-label="Permalink to &quot;Indicateur de compte et droit de réplication&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nom</th><th>Signification</th></tr></thead><tbody><tr><td><code>DONT_REQ_PREAUTH</code></td><td>Indicateur de <code>userAccountControl</code> qui dispense le compte de préauthentification Kerberos.</td></tr><tr><td><code>DS-Replication-Get-Changes</code></td><td>Droit étendu permettant de répliquer les modifications d’une partition de l’annuaire.</td></tr></tbody></table><p><a href="https://datatracker.ietf.org/doc/html/rfc4120" target="_blank" rel="noreferrer">Fonctionnement de Kerberos</a> · <a href="https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/useraccountcontrol-manipulate-account-properties" target="_blank" rel="noreferrer">Indicateurs de compte Microsoft</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/adschema/r-ds-replication-get-changes" target="_blank" rel="noreferrer">Droit de réplication Microsoft</a>.</p><h2 id="heure-linux" tabindex="-1">Vérifier l’horloge du poste Linux <a class="header-anchor" href="#heure-linux" aria-label="Permalink to &quot;Vérifier l’horloge du poste Linux {#heure-linux}&quot;">​</a></h2><p>Sur un poste Linux utilisant systemd, le service de gestion de l’heure doit être accessible.</p><h3 id="afficher-l-heure-et-le-fuseau-du-poste" tabindex="-1">Afficher l’heure et le fuseau du poste <a class="header-anchor" href="#afficher-l-heure-et-le-fuseau-du-poste" aria-label="Permalink to &quot;Afficher l’heure et le fuseau du poste&quot;">​</a></h3><p>Lis l’heure locale, le fuseau et l’état de la synchronisation affichés par systemd.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> status</span></span></code></pre></div><h3 id="lire-les-proprietes-de-synchronisation" tabindex="-1">Lire les propriétés de synchronisation <a class="header-anchor" href="#lire-les-proprietes-de-synchronisation" aria-label="Permalink to &quot;Lire les propriétés de synchronisation&quot;">​</a></h3><p><code>NTPSynchronized</code> indique si l’horloge est synchronisée et <code>TimeUSec</code> donne l’heure du système.</p><div class="language-bash vp-adaptive-theme"><button title="Copier le code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#FFA657;">timedatectl</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> show</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> NTPSynchronized</span><span style="--shiki-light:#005CC5;--shiki-dark:#79C0FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#A5D6FF;"> TimeUSec</span></span></code></pre></div><p><a href="https://www.freedesktop.org/software/systemd/man/latest/timedatectl.html" target="_blank" rel="noreferrer">Manuel de timedatectl</a> · <a href="https://www.freedesktop.org/software/systemd/man/latest/org.freedesktop.timedate1.html" target="_blank" rel="noreferrer">Propriétés de timedate1</a>.</p><h2 id="fiches-associees" tabindex="-1">Fiches associées <a class="header-anchor" href="#fiches-associees" aria-label="Permalink to &quot;Fiches associées&quot;">​</a></h2><ul><li><a href="./ad-enumeration">Énumération Active Directory</a></li><li><a href="./ad-techniques">Techniques Active Directory</a></li><li><a href="./ad-lateral">Mouvement latéral</a></li></ul><p>Source d’origine : <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">guide d’Emmanuel Solis</a>.</p>',20)]))}const m=t(o,[["render",s]]);export{p as __pageData,m as default};
